<script setup lang="ts">
import { ref, onMounted, nextTick, onBeforeUnmount, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import { GetBotAgentEdit, PostBotAgentCreate, PostBotAgentEdit, ParseBotAgent } from "@/apis/bot.ts";
import GameSelectionDialog from "@/components/bot/GameSelectionDialog.vue";
import { loadMonacoWithLanguage, loadMonacoLanguage } from "@/util/monaco";
import { GetHighlightKeyByJudgeLanguage, GetSubmitLanguages, JudgeLanguage } from "@/apis/language";

// monaco 实例将在动态加载后赋值
let monaco: typeof import("monaco-editor/esm/vs/editor/editor.api") | null = null;
import type {BotAgentView, BotGameView } from "@/types/bot.ts";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

const agentId = ref(0);
const isLoading = ref(false);
const isSaving = ref(false);

const languageOptions = ref([] as { label: string; value: JudgeLanguage | undefined }[]);
languageOptions.value = GetSubmitLanguages();

const agentEditForm = ref({
    name: "",
    gameId: 0,
    gameTitle: "",
    language: JudgeLanguage.Cpp as JudgeLanguage | undefined,
    code: "",
});

const agentData = ref<BotAgentView | null>(null);
let codeEditor: any = null;

// 游戏选择相关
const showGameDialog = ref(false);

// 初始化编辑器（异步加载 monaco）
const initEditor = async () => {
    const editorContainer = document.getElementById("code-editor-container");
    if (!editorContainer) return;

    // 动态加载 monaco 核心和当前语言
    const language = GetHighlightKeyByJudgeLanguage(agentData.value?.language);
    monaco = await loadMonacoWithLanguage(language);

    codeEditor = monaco.editor.create(editorContainer, {
        value: agentData.value?.code || "",
        language: language,
        minimap: { enabled: true },
        colorDecorators: true,
        readOnly: false,
        theme: "vs-dark",
        automaticLayout: false,
        scrollBeyondLastLine: false,
    });

    // 确保编辑器正确布局
    const updateEditorLayout = () => {
        if (codeEditor) {
            codeEditor.layout();
        }
    };

    nextTick(() => {
        updateEditorLayout();
    });

    // 添加窗口大小变化的事件监听器
    window.addEventListener('resize', updateEditorLayout);

    // 在组件销毁时移除事件监听器
    onBeforeUnmount(() => {
        window.removeEventListener('resize', updateEditorLayout);
        if (codeEditor) {
            codeEditor.dispose();
        }
    });
};

watch(isMobile, () => {
    if (codeEditor) {
        nextTick(() => {
            codeEditor.layout();
        });
    }
});

const handleSelectGame = () => {
    showGameDialog.value = true;
};

// 处理游戏选择
const handleGameSelect = (game: BotGameView) => {
    agentEditForm.value.gameId = game.id;
    agentEditForm.value.gameTitle = game.title;
    showGameDialog.value = false;
};

// 处理清除游戏选择
const handleGameClear = () => {
    agentEditForm.value.gameId = 0;
    agentEditForm.value.gameTitle = "";
    showGameDialog.value = false;
};

const onSelectLanguageChanged = async (value: JudgeLanguage): Promise<void> => {
    if (!codeEditor) {
        return;
    }
    const model = codeEditor.getModel();
    if (!model) {
        return;
    }
    const langKey = GetHighlightKeyByJudgeLanguage(value);
    // 动态加载选中语言的语法高亮
    await loadMonacoLanguage(langKey);
    monaco?.editor.setModelLanguage(model, langKey);
};

// 保存Agent
const saveAgent = async () => {
    if (!agentEditForm.value.name.trim()) {
        ShowTextTipsError(globalProperties, "请输入Agent名称");
        return;
    }

    if (!codeEditor) {
        ShowTextTipsError(globalProperties, "编辑器尚未初始化");
        return;
    }

    const code = codeEditor.getValue();
    if (!code.trim()) {
        ShowTextTipsError(globalProperties, "请输入代码");
        return;
    }

    if (!agentEditForm.value.gameId || agentEditForm.value.gameId <= 0) {
        ShowTextTipsError(globalProperties, "请选择游戏");
        return;
    }

    isSaving.value = true;

    try {
        let res;
        if (agentId.value) {
            // 编辑模式
            res = await PostBotAgentEdit(agentId.value, agentEditForm.value.name, agentEditForm.value.language, code, agentEditForm.value.gameId);
        } else {
            // 创建模式
            res = await PostBotAgentCreate(agentEditForm.value.name, agentEditForm.value.language, code, agentEditForm.value.gameId);
        }

        if (res.code !== 0) {
            ShowErrorTips(globalProperties, res.code);
            return;
        }

        ShowTextTipsSuccess(globalProperties, agentId.value ? "保存成功" : "创建成功");

        if (agentId.value && agentData.value) {
            agentData.value.version = res.data.version;
            agentData.value.modifyTime = new Date(res.data.modify_time).toLocaleString();
        } else {
            router.push({ name: "bot-agent-edit", params: { agentId: res.data } });
        }
    } finally {
        isSaving.value = false;
    }
};

// 加载Agent数据（编辑模式）
const loadAgent = async () => {
    isLoading.value = true;

    try {
        const res = await GetBotAgentEdit(agentId.value);
        if (res.code !== 0) {
            ShowErrorTips(globalProperties, res.code);
            await router.push({ name: "bot-agent-list" });
            return;
        }

        agentData.value = ParseBotAgent(res.data);

        // 填充表单数据
        agentEditForm.value.name = agentData.value.name;
        agentEditForm.value.language = agentData.value.language;
        if (agentData.value.code) {
            agentEditForm.value.code = agentData.value.code;
        } else {
            agentEditForm.value.code = "";
        }
        // 添加游戏相关字段的填充
        if (agentData.value.gameId) {
            agentEditForm.value.gameId = agentData.value.gameId;
        }
        if (agentData.value.gameTitle) {
            agentEditForm.value.gameTitle = agentData.value.gameTitle;
        }

        // 初始化编辑器
        nextTick(() => {
            initEditor();
        });
    } finally {
        isLoading.value = false;
    }
};

onMounted(() => {
    // 检查是否是编辑模式
    if (route.params.agentId) {
        agentId.value = Number(route.params.agentId);
        loadAgent();
    } else {
        // 创建模式，直接初始化编辑器
        initEditor();
    }
});

// 监听路由参数变化，处理从创建模式跳转到编辑模式的情况
watch(() => route.params.agentId, (newAgentId) => {
    if (newAgentId) {
        const parsedAgentId = Number(newAgentId);
        if (parsedAgentId !== agentId.value) {
            agentId.value = parsedAgentId;
            loadAgent();
        }
    }
});
</script>

<template>
    <t-loading :loading="isLoading">
        <t-row>
            <t-col :span="isMobile ? 12 : 8">
                <div style="margin: 10px">
                    <t-card class="sh-card">
                        <t-form :model="agentEditForm">
                            <t-form-item label="智能体名称">
                                <t-input v-model="agentEditForm.name" placeholder="请输入智能体名称"></t-input>
                            </t-form-item>
                            <t-form-item label="游戏">
                                <t-button theme="default" @click="handleSelectGame">{{ agentEditForm.gameTitle ||
                                    '请选择游戏' }}</t-button>
                            </t-form-item>
                            <t-form-item label="语言">
                                <t-select
v-model="agentEditForm.language" placeholder="请选择提交语言" auto-width clearable
                                    @change="onSelectLanguageChanged">
                                    <t-option
v-for="item in languageOptions" :key="item.value" :value="item.value"
                                        :label="item.label"></t-option>
                                </t-select>
                            </t-form-item>
                        </t-form>
                    </t-card>
                </div>
                <div class="dida-description-editor">
                    <p>代码</p>
                    <t-loading :loading="isSaving">
                        <div id="code-editor-container" class="code-editor"></div>
                    </t-loading>
                </div>
            </t-col>
            <t-col :span="isMobile ? 12 : 4">
                <div style="margin: 12px">
                    <div class="dida-edit-container">
                        <t-space>
                            <t-button theme="danger" :loading="isSaving" @click="saveAgent">
                                {{ agentId ? "保存" : "创建" }}
                            </t-button>
                            <t-button @click="router.back()">取消</t-button>
                        </t-space>
                    </div>
                    <t-descriptions layout="vertical" :bordered="true">
                        <t-descriptions-item v-if="agentId" label="ID">{{ agentId }}</t-descriptions-item>
                        <t-descriptions-item label="版本号">{{ agentData?.version }}</t-descriptions-item>
                        <t-descriptions-item label="创建时间">{{ agentData?.insertTime }}</t-descriptions-item>
                        <t-descriptions-item label="上传用户">{{ agentData?.inserterNickname }}</t-descriptions-item>
                        <t-descriptions-item v-if="agentData?.gameTitle" label="游戏名称">{{ agentData?.gameTitle
                            }}</t-descriptions-item>
                        <t-descriptions-item label="创建时间">{{ agentData?.insertTime }}</t-descriptions-item>
                        <t-descriptions-item v-if="agentData?.modifyTime" label="编辑时间">{{
                            agentData?.modifyTime }}</t-descriptions-item>
                        <t-descriptions-item v-if="agentData?.modifierNickname" label="修改用户">{{
                            agentData?.modifierNickname }}</t-descriptions-item>
                    </t-descriptions>
                </div>

                <div style="margin: 20px;border: 1px solid #ccc;padding: 12px;border-radius: 8px;">
                    <p>未避免可能的不兼容更新而产生异常，请添加QQ群来解锁测试权限：703659893</p>
                </div>
            </t-col>
        </t-row>
    </t-loading>

    <GameSelectionDialog v-model:visible="showGameDialog" @select="handleGameSelect" @clear="handleGameClear" />
</template>

<style scoped>
.dida-edit-container {
    margin: 10px 0;
    text-align: right;
}

.dida-description-editor {
    margin: 20px;
}

.code-editor {
    width: 100%;
    height: 800px;
    border: 1px solid #ccc;
    border-radius: 4px;
}

@media (max-width: 800px) {
    .dida-edit-container {
        margin: 6px 0;
    }

    .dida-description-editor {
        margin: 8px;
    }

    .code-editor {
        height: 60vh;
    }
}
</style>